import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/Dio110.html","title":"Dio110","lang":"en-US","frontmatter":{},"git":{"createdTime":1759035942000,"updatedTime":1759318871000,"contributors":[{"name":"Kazuma Arino","username":"","email":"hogeika2@gmail.com","commits":3}]},"readingTime":{"minutes":1.53,"words":459},"filePathRelative":"Dio110.md"}`),a={name:`Dio110.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="dio110" tabindex="-1"><a class="header-anchor" href="#dio110"><span>Dio110</span></a></h1><p><a href="./バイク.html">バイク</a>, <a href="./電動アシスト自転車.html">電動アシスト自転車</a></p><h1 id="dio110-1" tabindex="-1"><a class="header-anchor" href="#dio110-1"><span>Dio110</span></a></h1><p>2025年9月15日納車。現在のメインスクーター。</p><ul><li><a href="https://karino2.github.io/2025/09/12/switch_from_bike_to_scooter.html" target="_blank" rel="noopener noreferrer">バイクを処分してスクーターに乗り換えようと思う - なーんだ、ただの水たまりじゃないか</a></li><li><a href="https://karino2.github.io/2025/09/15/dio_first_impression.html" target="_blank" rel="noopener noreferrer">Dio 110をゲットしたぜ！ - なーんだ、ただの水たまりじゃないか</a></li><li><a href="https://karino2.github.io/2026/04/29/dio110_paswith_later.html" target="_blank" rel="noopener noreferrer">スクーターと電動アシスト自転車のその後 - なーんだ、ただの水たまりじゃないか</a> 2026年4月29日、一年弱乗った時点の感想</li></ul><h2 id="コンビニフック-2026-06-23-火" tabindex="-1"><a class="header-anchor" href="#コンビニフック-2026-06-23-火"><span>コンビニフック 2026-06-23 (火)</span></a></h2><p>コンビニフックがしょぼいなぁ、と思っていた所、楽天で安いのを見つけたので購入。</p><p><a href="https://a.r10.to/hPVjpm" target="_blank" rel="noopener noreferrer">楽天: アルミ コンビニフック 紫</a></p><p>340円。ネットで同じようなのをDio 110につけたという話があって、割と満足してそうだし、まぁこの値段なら試してみるか、と。 送料込みで340円は儲けあるのか？とか心配になってしまうが。</p><p>なぜか5日くらい郵便局で止められたが無事到着。</p><p>ついているのはソケットレンチで外すのにこのコンビニフックは六角レンチ。 どこまで閉めたらいいか良くわからない感じだが、まぁ外れなければいいだろう、と適当な所で妥協。</p><p>懸念していた邪魔という感じは今の所してない。 サーフボードベルトと干渉しないかは試してみたい所だが、普通に乗る分には足とかは当たらないな。</p><p>使ってみた。マイバックのとってが長過ぎて前のフックでは使えなかったのだが、 これに変えてからは2〜3重に巻けばちょうど良い感じに調整できて、 はずれそうな感じにもならずにいい感じだ。 マイバッグでの買い物は大分改善した。いいね！</p><h2 id="クロスストラップ-2026-05-10-日" tabindex="-1"><a class="header-anchor" href="#クロスストラップ-2026-05-10-日"><span>クロスストラップ 2026-05-10 (日)</span></a></h2><p>ノートPCカバンをいい感じにDio110で運びたい。なんかシートに固定したりするのは面倒だし走っている時に不安もあるので、もっと気軽にしたい。</p><p>現状は肩かけカバンで後ろのシートに乗っけている感じなのだが、概ね良いのだが、たまにぶらぶらするのでもう一歩という感じがある。 なんかベルトで体に固定すればいいのでは？と少しCopilotに相談して、以下にたどり着く。</p><p><a href="https://amzn.to/3P5E09D" target="_blank" rel="noopener noreferrer">amazon: Ｏｋｉｍａ クロスストラップ</a></p><p>980円なのでホムセンなどで似たような何かを調達しても似たような値段だろう、という事でこれを買ってみる。</p><h2 id="近場の峠を越えてくる-2025-09-20-土" tabindex="-1"><a class="header-anchor" href="#近場の峠を越えてくる-2025-09-20-土"><span>近場の峠を越えてくる 2025-09-20 (土)</span></a></h2><p>この辺はあとでブログに移したいな。</p><p>近場のダイソーやハードオフを回った。結局目当てのものは良いのがなくてAmazonでポチる事になったが。</p><p>ただ、こうやって近場を回るのは楽しい。 いやぁ、やっぱ楽だわ。軽い。駐車場引いて歩くのもなんでも無い。駐車も簡単。 これまで行く気が起こらなかった自転車の行動範囲の一回り外側を回るのがなんでも無い。 行動範囲が広がった。</p><p>250ccの方が当然遠くまで行けるのだが、遠くまで行かないと乗る気が起こらないので、 今回回ったような範囲を回るのは結構億劫なんだよな。 そういう訳で自転車と250ccの間には何でも面倒な範囲というのが結構広がっていた。 そこがDio 110にドンピシャで、これまであまり行かなかったあたりに気軽に行けるようになった。いいね。</p><p>ついでに、この辺で一番の峠である朝比奈を越えて帰ってきたが、前の車が詰まっててパワー不足かどうかを試す事は出来なかった。 だいたいここの峠はこうなるので、ここではパワー不足では無いという結論でいいような気もするが。 むしろ間の信号が多い所でのストップアンドゴーが楽なので、以前よりも気軽に越えられる気がする。</p><p>走ってる時も凄い楽なんだが、この楽さはどこからくるのかなぁ、とか考えていて、 今日は曲がる時とか停止する時に車体を傾けたりするのが意外と力を使っていた、 という結論になる。 重さがあるので疲れていたんだよなぁ。Dio 110は近場を回るだけだと全然疲れない。</p><p>Dio 110を手に入れてから、渋滞さえ無い時間なら、逗子とか東逗子とかちょっとした距離なら何も気にせず出る事ができるようになった。 大船とか藤沢も開拓していきたい。</p><p>そういえばパワーが足りない、と思うシチュエーションはたまにある。 たらたら40kmくらいで走っていたところ、前に原付がいて抜かそうと加速しようとした時にちょうど上り坂だったりすると、 加速が遅い。 上り坂でも巡航速度で60kmくらいは出るが、60kmまで加速するのは大変だ。 上り坂での追い越しは、そのままの速度で自然に抜かせるケースに限った方が良さそう。</p><p>あと、向かい風がめちゃ強い時も進まない、ってなった。アクセル全開で40kmくらいしか出なかった。 ただ風強すぎてバイク乗りたくないシチュエーションなので、ここがどうなのかはどうでも良い、という気はした。（どちらにせよ嫌なので）</p><p>という事でもっとパワーが欲しいとはそれほど思わないが、パワー不足な事はあるな。</p>`,29)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};